    done = re.search(r'^GATES CHAIN DONE — (ALL GREEN|FAILURES ABOVE) — (\d\d:\d\d)$', text, re.M)
    return rows, (done.group(1) if done else 'PARTIAL'), (done.group(2) if done else '')
